'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var Float64Array = require( '@stdlib/array/float64' );
var abs = require( '@stdlib/math/base/special/abs' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dpbtf2 = require( './../lib' );


// FUNCTIONS //

/**
* Creates a bounded reset-and-factor benchmark with reconstruction checks.
*
* @private
* @param {PositiveInteger} N - matrix order
* @param {boolean} upper - whether to store the upper triangle
* @param {boolean} failed - whether the first diagonal is zero
* @returns {Function} benchmark function
*/
function createBenchmark( N, upper, failed ) {
	var original;
	var AB;
	var r;
	var c;
	var o;
	var i;
	var j;

	original = new Float64Array( 2*N );
	AB = new Float64Array( 2*N );
	r = 1;
	c = -2;
	o = 2*(N-1);
	for ( i = 0; i < original.length; i++ ) {
		original[ i ] = 999.0;
	}
	for ( j = 0; j < N; j++ ) {
		original[ o+(( ( upper ) ? 1 : 0 )*r)+(j*c) ] = ( failed && j === 0 ) ? 0.0 : N+4.0;
		if ( upper && j > 0 ) {
			original[ o+(j*c) ] = 0.25;
		} else if ( !upper && j+1 < N ) {
			original[ o+r+(j*c) ] = 0.25;
		}
	}
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var expected;
		var diagonal;
		var previous;
		var coupling;
		var star;
		var info;
		var i;
		var j;

		expected = ( failed ) ? 1 : 0;
		info = -9;
		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			// Input reset is included in the measured workload:
			AB.set( original );
			info = dpbtf2.ndarray( ( upper ) ? 'upper' : 'lower', N, 1, AB, r, c, o );
			if ( info !== expected ) {
				b.fail( 'should produce the expected factorization status' );
				b.end();
				return;
			}
		}
		b.toc();
		if ( failed ) {
			for ( i = 0; i < AB.length; i++ ) {
				if ( AB[ i ] !== original[ i ] ) {
					b.fail( 'should stop before the first factor write' );
					b.end();
					return;
				}
			}
		} else {
			previous = 0.0;
			for ( j = 0; j < N; j++ ) {
				diagonal = AB[ o+(( ( upper ) ? 1 : 0 )*r)+(j*c) ];
				if ( j > 0 ) {
					coupling = ( upper ) ? AB[ o+(j*c) ] : AB[ o+r+((j-1)*c) ];
					if ( !( abs( (previous*coupling)-0.25 ) <= 1.0e-12 ) ) {
						b.fail( 'should reconstruct each input off-diagonal' );
						b.end();
						return;
					}
				} else {
					coupling = 0.0;
				}
				if ( !( diagonal > 0.0 ) || !( abs( (diagonal*diagonal)+(coupling*coupling)-(N+4.0) ) <= 1.0e-11 ) ) {
					b.fail( 'should reconstruct each positive input diagonal' );
					b.end();
					return;
				}
				previous = diagonal;
			}
		}
		star = ( upper ) ? o : o+r+((N-1)*c);
		if ( AB[ star ] !== 999.0 ) {
			b.fail( 'should preserve the unused band corner' );
			b.end();
			return;
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var options;
	var sizes;
	var name;
	var fcn;
	var i;
	var j;
	var k;

	options = {
		'iterations': 200,
		'repeats': 2
	};
	sizes = [ 8, 16 ];
	for ( i = 0; i < sizes.length; i++ ) {
		for ( j = 0; j < 2; j++ ) {
			for ( k = 0; k < 2; k++ ) {
				name = format( '%s:ndarray:N=%d:triangle=%s:first=%s', pkg, sizes[ i ], ( j ) ? 'upper' : 'lower', ( k ) ? 'zero' : 'positive' );
				fcn = createBenchmark( sizes[ i ], j === 1, k === 1 );
				bench( name, options, fcn );
			}
		}
	}
}

main();
